import '@design-schema/lit';
import { html, type TemplateResult } from 'lit';
import type { TextAlign, TextElement, TextSize, TextTone, TextWeight } from '@design-schema/lit';

interface TextArgs {
  size: TextSize;
  weight: TextWeight;
  tone: TextTone;
  align: TextAlign;
  truncate: boolean;
  element: TextElement;
  /** The slotted text content (the doc's `children`). */
  children: string;
}

function renderText(args: TextArgs): TemplateResult {
  return html`
    <ds-text
      size=${args.size}
      weight=${args.weight}
      tone=${args.tone}
      align=${args.align}
      ?truncate=${args.truncate}
      element=${args.element}
      >${args.children}</ds-text
    >
  `;
}

html`
  <div style="background: var(--color-action-primary-background)">
    <ds-box inset="md">${renderText({ tone: 'onAction', children: 'Changes are saved automatically. You can undo any change for 30 days.' })}</ds-box>
  </div>
`;

